from pathlib import Path
import json,hashlib,base64,subprocess,sys,time,datetime,resource,zipfile,os
root=Path('/content/tep225-exact');root.mkdir(exist_ok=False)
payloads={'capped_matrix_rectangles_diagnostic225.py': '', 'capped-matrix-rectangles225-draft.txt': ''}
pins={'capped_matrix_rectangles_diagnostic225.py': 'c53c38691d00a20b5168abc7cc4483e07b1c95444f99229fa866714d9f97c474', 'capped-matrix-rectangles225-draft.txt': 'a9c4bcbc3b8764b2e2cf84b7906ae5fe9ed3fa96c5f5ae22c68eb665a0f7d448'}
for name,b64 in payloads.items():
 raw=base64.b64decode(b64)
 if hashlib.sha256(raw).hexdigest()!=pins[name]:raise ValueError('Input pin')
 (root/name).write_bytes(raw)
report={'started_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'source_context':'sourced4d658623ab8602f6ddba73c93e3a012817fa486','input_pins':pins,'python':sys.version,'runtime':'Own Colab Linux CPU high-memory; no scientific work on Windows','compute_units_billed':None,'exits':{}}
start=time.monotonic()
for mode,args in [('normal',[]),('optimized',['-O'])]:
 p=subprocess.run([sys.executable]+args+[str(root/'capped_matrix_rectangles_diagnostic225.py')],capture_output=True)
 (root/(mode+'.stdout')).write_bytes(p.stdout);(root/(mode+'.stderr')).write_bytes(p.stderr)
 tmp=root/(mode+'.exit.tmp');tmp.write_text(str(p.returncode)+'\n');os.replace(tmp,root/(mode+'.exit'))
 report['exits'][mode]=p.returncode
 if p.returncode:break
ok=report['exits']=={'normal':0,'optimized':0}
if ok:
 ok=(root/'normal.stdout').read_bytes()==(root/'optimized.stdout').read_bytes()
 if ok:
  v=json.loads((root/'normal.stdout').read_bytes());ok=v['status']=='SELECTED_EXACT_MATRIX_REFINEMENT_DIAGNOSTICS_CHECKED' and v['negative_controls_rejected']==4 and len(v['cases'])==7
report.update(status='FINITE_DIAGNOSTICS_CHECKED' if ok else 'FAILED_PRESERVED',finished_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),elapsed_seconds=time.monotonic()-start,child_maxrss_kib=resource.getrusage(resource.RUSAGE_CHILDREN).ru_maxrss,normal_optimized_output_equal=ok,source_audit_pending=False)
(root/'report.json').write_text(json.dumps(report,indent=2)+'\n')
items=[{'file':p.name,'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in sorted(root.iterdir()) if p.is_file()]
(root/'MANIFEST.json').write_text(json.dumps({'files':items},indent=2)+'\n')
z=Path('/content/tep225-diagnostics.zip')
with zipfile.ZipFile(z,'w',zipfile.ZIP_DEFLATED) as archive:
 for p in sorted(root.iterdir()):archive.write(p,p.name)
print(json.dumps({'report':report,'zip':str(z),'sha256':hashlib.sha256(z.read_bytes()).hexdigest()}))
if not ok:raise SystemExit(1)
